def solve(nums):
    """Return the length of the longest strictly increasing subsequence."""
    tails = []  # tails[i] = smallest tail of an increasing subsequence of length i+1
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

