def solve(grid):
    """Count islands in a binary grid (batch 2).
    An island is a group of orthogonally connected cells with value 1.
    Returns the number of islands as an integer.
    Handles empty grid and empty rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows and isinstance(grid[0], (list, tuple)) else 0
    if cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= cols:
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

