def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting method with binary search for O(n log n).
    """
    import bisect
    if not nums:
        return 0
    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # Find insertion point
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

