def solve(tokens):
    """Evaluate Reverse Polish Notation tokens (batch 2).
    Supports '+', '-', '*', '/' with integer division truncating toward zero.
    Returns 0 for empty input.
    """
    if not tokens:
        return 0
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division, truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0] if stack else 0
